Method.Implementation:
	// Set usrNm = $username
	set files = ""
	set SelectedIntfiles = ""
	Set filesList= ##class(%Library.ListOfDataTypes).%New()

	if ( (Selectedfiles = "") || (comment = "") )
	{
		Quit $$$ERROR($$$EnsErrGeneral, "FileNames and comment are empty")
	}
	For I=1:1:$L(Selectedfiles,",")
	{
		Set fileNm = $P(Selectedfiles,",",I)

		if ( fileNm '= "")
		{
		   SET files = files _ " " _ fileNm 
	    }
	    else
	    {
		    continue
	    }
	    Do ..AddDirectoriesToSvn(fileNm, usrNm, passwd)

        // Get latest from Ensemble DB 

	    set InternalName = ..GetInternalName(fileNm)
	    IF InternalName '= "" 
        {
	        set sc = $$$OK
	        Set origNmSp =  $NAMESPACE
	        Set $NAMESPACE = nmSp
	        if ($F(InternalName, ".LOOKUP") > 0)
	        {
		        // Table name is between Namespace - first field and LOOKUP - last field
		        // Example: 
		        // Intername name: RESULTS.IHC.ITF.Process.Bpl.PowerPathReultsHl7To4Medica.Lookup.MedicaLocations.LOOKUP
		        // Table Name: IHC.ITF.Process.Bpl.PowerPathReultsHl7To4Medica.Lookup.MedicaLocations

		        // Strip namespace before first .
		        set tbNm = $E(InternalName, $F(InternalName,"."), *)
		        // String LOOKUP at the end
		        set tbNm = $E(tbNm, 1, ($F(tbNm,"LOOKUP") - 8))

		        Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Export lookup table: " _ tbNm _ " to " _ fileNm)
		        set sc = ##class(Ens.Util.LookupTable).%Export(fileNm, tbNm)
	        }
	        elseif ($F(InternalName, ".SYSDEF") > 0)
	        {
		        set prodNm = ##class(Ens.Director).GetActiveProductionName()
    			set sc = ##class(Ens.Config.DefaultSettings).%Export(fileNm, prodNm)
    			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Export System defaults " _ prodNm _ " to " _ fileNm _ ", stat: " _ sc)
	        }
	        elseif ($F(InternalName, ".TASK") > 0)
	        {
		        // Strip namespace before first .
				set taskNm = $E(InternalName, $F(InternalName,"."), *)
				// String TASK at the end
				set taskNm = $E(taskNm, 1, ($F(taskNm,"TASK") - 6))
				Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Get task id for: " _ taskNm)
  				&sql(SELECT ID into idNum FROM %SYS.Task where Name = :taskNm)
     			IF (SQLCODE = 0)
				{
		 			set sc = ##class(%SYS.Task).ExportTasks($Lb(idNum), fileNm)

	    			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Export Task " _ taskNm _ " to " _ fileNm _ ", stat: " _ sc)
	        	}
	        	else
	        	{
		        	set sc = $$$ERROR("SQL error: " _ SQLCODE)
		        	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "Can not get task Id for " _ taskNm _ ", " _ sc)
	        	}
	        }
	        else {
	        	Set sc=$$Export^%occXMLExport(fileNm,"-d /diffexport",InternalName)
	        	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("occXMLExport: " _fileNm _ ", " _ InternalName _"Stat: " _sc)
	        }
	        Set $NAMESPACE = origNmSp
	        if ( ($$$ISOK(sc)) &&  (##class(%Library.File).Exists(fileNm)) )
	        {
	          set SelectedIntfiles = SelectedIntfiles _ "," _ InternalName
         	  Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("CheckinFiles: " _ $NAMESPACE _ " " _ fileNm _" -d /diffexport " _InternalName)
	          Do ..AddToSvn(fileNm, 0, usrNm, passwd)
	          Do filesList.Insert(fileNm)	
	        }
	        else
	        {
		          Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("CheckinFiles: file does not exits: " _ fileNm _" -d /diffexport " _InternalName)

	        }
        }
	}

	if (files '= "" )
    {

	    Set cmd = $$$SVNCOMMIT _ " --username " _ usrNm _ " --password '" _ passwd  _ "' -m "" " _ comment _ " "" " _ files  ; a non-recursive commit (-N)
	    Set stat = ##class(IHC.ITF.SrcCtrlPkg.ItfSrcCtrlUtil).ExecuteShellCmd( cmd)

        Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("CheckinFiles: commit " _ files _ ", stat: " _ stat)

		if stat '= 0
		{
		  Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("SVN commit error: " _ files)
		  Quit $$$ERROR($$$EnsErrGeneral, "SVN commit error")
		}

    }
    Do ..AddSvnFilesToSourceControl(filesList, usrNm, nmSp )

     Quit $$$OK

 NEW $NAMESPACE
 SET $NAMESPACE = "ITFCOMMON"
 &sql(SELECT TOP 1 InternalName INTO :intName FROM IHC_ITF_SrcCtrlPkg.SrcCtrlTbl WHERE FileName=:fileNm)
 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("GetInternalName, SQLCODE: " _ SQLCODE _ ", Name: " _ fileNm _ " : " _ intName)

 IF SQLCODE = 0 
 { 
	   return intName
 }
 else
 {
        return ""
 }

// Set usrNm = $username
set stat = $$$ERROR(9100, "Could not add")
SET fullPath = $$$USRBASEDIR _ usrNm _ $$$SVNSRCTRUNK
set svnPath=$REPLACE(fName, fullPath, "")
Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("AddDirectoriesToSvn " _ fullPath _ " = " _svnPath) 
SET fileParts = $Length(svnPath, "/")
// Check if directories from SVN BASE exists or not
FOR ind=1:1:fileParts - 1
{
	set dirName = $PIECE(svnPath, "/", ind)
	set fullPath = fullPath _ "/" _ dirName
	if ( ' ##class(%Library.File).Exists(fullPath))
	{
		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("AddDirectoriesToSvn, create directory: " _fullPath)
		Do ##class(%File).CreateDirectory(fullPath)
	}
	Do ..AddToSvn(fullPath, 1, usrNm, passwd)
}


	set tStatus = $$$ERROR(100, "Error in checkout")
	Set filesList= ##class(%Library.ListOfDataTypes).%New()

	if (Selectedfiles = "")
	{
		Quit $$$ERROR(6484, "FileName")
	}
	For I=1:1:$L(Selectedfiles,",")
	{
		Set fileNm = $P(Selectedfiles,",",I)
		if ( fileNm '= "")
		{	 
			If ##class(%File).Exists(fileNm)
			{
	  			Do ##class(%File).Delete(fileNm)
	  			 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Delete old version of file: " _ fileNm)
			}	
			if (rev '= "")
			{
				Set cmd= $$$SVNUPDATE _ " --revision " _ rev
			}
			else
			{		
			  Set cmd= $$$SVNUPDATE 
			}
			Set cmd= cmd _ " --username " _ usrNm _ " --password '" _ passwd _ "' " _  fileNm 

			Set status = ##class(IHC.ITF.SrcCtrlPkg.ItfSrcCtrlUtil).ExecuteShellCmd( cmd)
			If ##class(%File).Exists(fileNm)
			{
				Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("File Exists, checkout: " _ fileNm _ ": " _ status)
				Set origNmSp =  $NAMESPACE
				NEW $NAMESPACE
	           	Set $NAMESPACE = nmSp
	           	Do filesList.Insert(fileNm)

				if ($F(fileNm, "/lookupTables/") > 0)
	        	{
		        	set intNm = ..GetInternalName(fileNm)
		        	if ($LENGTH(intNm) > 0)
		        	{
		        		// Remove Namespace in front and LOOKUP at the end of the name
		        		set tbNm = $EXTRACT(intNm, $FIND(intNm, "."), ($F(intNm,"LOOKUP") - 8))

		        		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile($NAMESPACE _ " LookupTable name: " _ tbNm)
		        		if ($$$ISOK( ##class(Ens.Util.LookupTable).%ExistsTable(tbNm)))
		        		{
			        		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile($NAMESPACE _ " Clear the table")
		        			Do ##class(Ens.Util.LookupTable).%ClearTable(tbNm)

		        		}
		        	}
		        	set tStatus = ##class(Ens.Util.LookupTable).%Import(fileNm, "", .cnt)
		        	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile($NAMESPACE _ " LookupTable Import " _ fileNm _ ", stat: " _ tStatus _ ", entries: " _ cnt)
	        	}
	        	 elseif ($F(fileNm, "systemDefaults/") > 0)
	        	{
		        	set pc = 0
    				set tStatus = ##class(Ens.Config.DefaultSettings).%Import(fileNm, .pc)
    				Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile($NAMESPACE _ " DefaultSettings Import System defaults stat: " _ tStatus _ ", # " _ pc)
	        	}
	        	elseif ($F(fileNm, "tasks/") > 0)
	        	{
   				    set tStatus = ##class(%SYS.Task).ImportTasks(fileNm)
    				Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile(" ImportTasks stat: " _ tStatus _ ", file " _ fileNm)
	        	}
	        	else
	        	{	  		  
         	   		#; Call the function to do the load        	   		
         	   		Set tStatus=$system.OBJ.Load(fileNm,"-l-d-c")        	   		
	        	}

         	   if $$$ISOK(tStatus)
         	   { 
         		 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile($NAMESPACE _ " File Loaded: " _ fileNm _ ": " _ tStatus)
         		 set intNm = ..GetInternalName(fileNm)
         		 if (intNm = "")
         		 {
	         		 // when a new file is loaded, get the internal name by getting all classes
         		 	Do ..getAllEnsembleItems(usrNm , passwd , nmSp )
         		 }
         		 set intNm = ..GetInternalName(fileNm)
         		 if (intNm '= "")
         		 {
         	   	 	Do ..AddToSourceControl(intNm, usrNm, nmSp)
         		 }
         		 else
         		 {
	         		  Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile($NAMESPACE _ "Can't get internal name for " _fileNm)
         		 }
         		 set tStatus = $$$OK       
	  		   }
	  		   else
	  		   {
		  		   Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile($NAMESPACE _ " _ File load failed: " _ fileNm)
	  		   }
	  		   if ($F(fileNm, "DStruc/") > 0)
	        	{
		        	set intNm  = ..GetInternalName(fileNm)
		        	// Remove Namespace in front and CLS at the end of the name
		        	set recCls = $EXTRACT(intNm, 1, ($F(intNm,"CLS") - 5))

		        	if (##class(EnsLib.RecordMap.RecordMap).Exists(recCls))
		        	{
			        	Set tStatus = ##class(EnsLib.RecordMap.Generator).GenerateObject(recCls,,1,,2,0,"ck",0,.tGenList,0)
						If $$$ISERR(tStatus) {
	    					Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("GenerateObject " _ $System.Status.GetErrorText( tStatus))
	    					Quit tStatus
    					}
						// Get all generated classes
						Set tClass = ""
						For {
							Set tClass = $order(tGenList(tClass))
							Quit:(tClass = "")
							Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "Generated Class: " _ tClass)
						}
		        	}
		        	else
		        	{
    					Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile(recCls _ " is not EnsLib.RecordMap.RecordMap")
    					set tStatus = $$$ERROR(100, recCls _ " is not EnsLib.RecordMap.RecordMap")
		        	}
	        	}
	           Set $NAMESPACE = origNmSp
			}
			else
			{
				Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( $$$SVNUPDATE _ " failed: " _ fileNm)
				set tStatus = $$$ERROR(100, "Error in checked from subversion")
			}
		}
	}
	 Do ..AddSvnFilesToSourceControl(filesList, usrNm, nmSp )
	Quit tStatus


	set fileInfo = ""

	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("GetSvnInformation " _ $NAMESPACE _ " " _ usrNm _ " " _ Selectedfiles)
	if (Selectedfiles = "")
	{
		Quit $$$ERROR(6484, "FileName")
	}
	For I=1:1:$L(Selectedfiles,",")
	{
		Set fileNm = $P(Selectedfiles,",",I)
		set tempFile = 	fileNm _ "Temp"
		if (##class(%File).Exists(tempFile) )
	  	{
			Do ##class(%Library.File).Delete(tempFile)
	  	}
		if ( (fileNm '= "") && (##class(%File).Exists(fileNm) ) )
		{	 


	         Set cmd= $$$SVNINFO _ fileNm _ " >> " _ tempFile

			 Set status = ##class(IHC.ITF.SrcCtrlPkg.ItfSrcCtrlUtil).ExecuteShellCmd( cmd)

	         Set cmd=  $$$SVNLOG _" --username " _ usrNm _ " --password '" _ passwd _ "' " _ fileNm _ " >> " _ tempFile 

			 Set status = ##class(IHC.ITF.SrcCtrlPkg.ItfSrcCtrlUtil).ExecuteShellCmd( cmd)

	  		if (##class(%File).Exists(tempFile) )
	  		{
         		#; Call the function to do the load
         		Set tStatus=..GetFileContent(tempFile) 
         		Set fileInfo = fileInfo _ tStatus       
	  		}
	  		else
	  		{
		  		SET fileInfo = "svn command failed: " _ cmd
	  		}
		}
		elseif (fileNm '= "")
		{
			SET fileInfo = fileInfo _ " Failed find file: " _ fileNm
		}
	}
	Quit fileInfo


	set fileInfo = ""

	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("GetDiff: " _ Selectedfiles)
	if (Selectedfiles = "")
	{
		Quit $$$ERROR(6484, "FileName")
	}
	For I=1:1:$L(Selectedfiles,",")
	{
		Set fileNm = $P(Selectedfiles,",",I)
		set tempFile = 	fileNm _ "Temp"
		set diffFile = 	fileNm _ "Diff"
		if (##class(%File).Exists(tempFile) )
	  	{
			Do ##class(%Library.File).Delete(tempFile)
	  	}
	  	if (##class(%File).Exists(diffFile) )
	  	{
			Do ##class(%Library.File).Delete(diffFile)
	  	}
     if ( (fileNm '= "") && (##class(%File).Exists(fileNm) ) )
     {

     set InternalName = ..GetInternalName(fileNm)
	 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile(fileNm _ " = " _ "Int name: " _ InternalName)
	 IF InternalName '= "" 
     { 
     		Set origNmSp =  $NAMESPACE
	        Set $NAMESPACE = nmSp
	       Set sc=$$Export^%occXMLExport(tempFile,"-d /diffexport",InternalName)
	       Set $NAMESPACE = origNmSp
     }
     if (  ##class(%File).Exists(tempFile)) 
     {
	    Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "file exists: " _ tempFile)
	    set cmd = "diff -w -B --suppress-common-lines " _ tempFile _ " " _ fileNm _ " > " _ diffFile
	    Set stat = ##class(IHC.ITF.SrcCtrlPkg.ItfSrcCtrlUtil).ExecuteShellCmd( cmd)
	    Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile(diffFile)
	    Set diffStr = ..GetFileContent(diffFile) 
	    if (diffStr = "")
	    {
		     set fileInfo = fileInfo  _ "<BR>" _ fileNm _ ": Files are identical"
	    }
	    else
	    {
		    set fileInfo = fileInfo  _ "<BR>" _ fileNm _ "<BR> < Source control <BR> > Ensemble file" _ diffStr
	    }
	    Do ##class(%Library.File).Delete(tempFile)
	    Do ##class(%Library.File).Delete(diffFile)
     }
	}
	}
	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Diff: " _ fileInfo)
	Quit fileInfo


	set outputStr = "Downloaded files: "

	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("DisplayFiles: " _ Selectedfiles _ " " _ usrNm)
	if (Selectedfiles = "")
	{
		Quit $$$ERROR(6484, "FileName")
	}
	For I=1:1:$L(Selectedfiles,",")
	{
		Set fileNm = $P(Selectedfiles,",",I)

     if ( fileNm = "") 
     {
	     continue
     }
     if ( ##class(%File).Exists(fileNm) ) 
     {
	    set newFileNm = $$$USRBASEDIR _ usrNm _ "/" _ ##class(%File).GetFilename(fileNm)
        if ( ##class(%File).CopyFile(fileNm, newFileNm, 1) = 0)
        {
	        set outputStr = "Could not create file: " _ newFileNm
	        Quit
        }
        else
        {
	        set outputStr = outputStr  _ newFileNm _ "; "
        }
     }
     else
     {
	     set outputStr = outputStr  _ "; Could not find file: " _ fileNm
	     Quit
     }
	}

	Quit outputStr

set tempFile = $$$USRBASEDIR _ usrNm _ "/tempSvnList"
 Do ##class(%File).Delete(tempFile)
 return ..CreateListOfFilesInSvn(usrNm, passwd, nmSp)


	 NEW $NAMESPACE
    SET $NAMESPACE = "ITFCOMMON"

	// All files for ITFCOMMON namespace will be under IHC
	set numFiles = 0

	set tempFile = $$$USRBASEDIR _ usrNm _ "/tempSvnList"
	set fileInfo = ""

 	set fullPath =  $$$USRBASEDIR _ usrNm _  $$$SVNSRCTRUNK 

 	Set cmd = $$$SVNUPDATEALL _ " --username " _ usrNm _ " --password '" _ passwd _ "' " _ fullPath 
    Set stat = ##class(IHC.ITF.SrcCtrlPkg.ItfSrcCtrlUtil).ExecuteShellCmd( cmd)
    Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("GetFilesInSvn: " _ $$$SVNUPDATEALL _ " for " _ fullPath _": "_stat)

    Set cmd = $$$SVNINFO _ " -R --username " _ usrNm _ " --password '" _ passwd  _ "' " _ fullPath _ " | grep -E ""URL|Kind|Last Changed"" > " _ tempFile
	Set stat = ##class(IHC.ITF.SrcCtrlPkg.ItfSrcCtrlUtil).ExecuteShellCmd( cmd)

	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( $$$SVNINFO _ "for " _ fullPath _" : " _ stat)

	If ( ##class(%File).Exists(tempFile) = 0)
	{
		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "Did not create file: " _ tempFile)
		Quit
	}

	Set fileObj=##class(%Library.File).%New(tempFile)
         set fileOpen = fileObj.Open("RS") ; Read mode and as stream
        set int = 1
        set isFile = 0
         While 'fileObj.AtEnd 
         {
	         set readStr = fileObj.ReadLine(1000, .sc, .stat)
	         if ($L(readStr) > 0)
	         {
		         if (readStr [ "URL:")
		         {
			         set file = $$$USRBASEDIR _ usrNm _  $$$SVNSRCTRUNK_ $E(readStr, $F(readStr, $ZSTRIP($$$SVNSRCURL, "*W") _ "/"), *)

		         }
		         elseif(readStr [ "Node Kind: file")
		         {		         
			         set int = int + 1
			         set isFile = 1
		         }
		         elseif(readStr [ "Rev: ")
		         {
			         set rev = $E(readStr,  $F(readStr , "Rev: "), *)
		         }
		         elseif(readStr [   "Date: ")
		         {
			         if (isFile = 1)
			         {
			       		set fileStamp = $E(readStr,  $F(readStr , "Date: "), $F(readStr , " -") -3)

			       		set isFile = 0
			       		set updStr = rev
			       		set oper = "UPDATE"
			       		&sql(UPDATE  IHC_ITF_SrcCtrlPkg.SrcCtrlTbl SET FileModifiedTime=:fileStamp, Comment = :updStr WHERE FileName=:file )
			       		if SQLCODE '= 0 {
				       		set oper = "INSERT"
	       					&sql(INSERT INTO IHC_ITF_SrcCtrlPkg.SrcCtrlTbl (FileName, Username, FileModifiedTime) VALUES (:file, :usrNm, :fileStamp))
        				}
        				Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( int _ ". " _ oper _ " - " _ file _ ", " _ rev _ ", " _ fileStamp _ ", SQLCODE: " _ SQLCODE)
        				set numFiles = numFiles + 1
			         }
		         }

	         }	       
         }
         Do fileObj.Close()
         set $NAMESPACE = nmSp
         Return numFiles

	set fileInfo = ""
	Set fileObj=##class(%Library.File).%New(TempFile)
         set fileOpen = fileObj.Open("RS") ; Read mode and as stream
         Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("OPEN: " _ fileOpen)
         While 'fileObj.AtEnd 
         {
	         set readStr = fileObj.ReadLine(1000, .sc, .stat)
	         if ($L(readStr) > 0)
	         {
	        	set fileInfo = fileInfo _ ..HTMLEncode(readStr) _ "<BR>"
	         }	       
         }
         Do fileObj.Close()
         if (delete)
         {
           Do ##class(%Library.File).Delete(TempFile)
         }
         Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("file len: " _ $LENGTH(fileInfo))
         Quit fileInfo


	#dim tStat as %Status

	set itNum = 0
	try
	{
		set dtTm = ..GetLastLoadTime(usrNm, nmSp)
		if ( dtTm '= "")
		{
	 		set dt = $PIECE($ZDATETIMEh(dtTm, 3, 1), ",", 1)
			set tm = $PIECE($ZDATETIMEh(dtTm, 3, 1), ",", 2)

			set dtN = $PIECE($NOW(), ",", 1)
			set tmN = $PIECE($NOW(), ",", 2)
		}

		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("UpdateItemsInfoToSrcCtrlTbl: GetLastLoadTime " _ usrNm _ ", " _ dtTm)
		if ( dtTm = "" || (dt '= dtN ))
		{
			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("UpdateItemsInfoToSrcCtrlTbl: CheckSvnSetup- ") 
	  		set tStat = ..CheckSvnSetup(usrNm, passwd)

	  		IF $$$ISERR( tStat )
	  		{
		  	set tExp = ##class(%Exception.General).%New()
		  	set tExp.Name = "Setup error: " _ tStat.Data
		  	set tExp.Code=999
		  	set tExp.Location = "CheckSvnSetup"
		  	set tExp.Data = "Check: " _ $$$USRBASEDIR _ usrNm
		  	Throw tExp
	  		}
		}
	  try
	  {
	 	 NEW $NAMESPACE
      	 SET $NAMESPACE = nmSp
	  } catch err
	  {
		  Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Not able change to " _ nmSp _ ". Error: " _ err.Name _ " " _ err.Location)
		throw err
	  }

   	  Do ..CreateListOfFilesInSvn(usrNm, passwd, nmSp) 

	  Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("GetItems " _ $NAMESPACE _ " " _ usrNm)


      set itNum = ..getAllEnsembleItems(usrNm , passwd , nmSp ) 

	  Do ..UpdateLastLoadTime(usrNm, nmSp)
	} catch err
	{
		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("EXCEPTION in GetItems: " _ err.Name _ " " _ err.Location)
		throw err
	}
	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Return from GetItems, # of items: " _ itNum)
	set numRows = itNum
	return $$$OK

	 NEW $NAMESPACE
      	 SET $NAMESPACE = nmSp
	set itNum = 0
	set prodNm = ##class(Ens.Director).GetActiveProductionName()
	  Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile(" GetItemsFromProduction from " _ prodNm)
	  Set tProduction = ##class(Ens.Config.Production).%OpenId(prodNm,,.tSC)
