   		FOR reps=countdown:-1:1 {
      		SET extract=$PIECE(cmd,delim,countup)
           	if ( ($L(extract) '= 0) && (extract '= " ") ) {
	           	if ( (extract = """") && (multiWord = 0) )
	           	{
		           	set multiWord = 1
		           	SET countup = countup+1
		           	SET cmdArr(arrInd) = ""
		           	CONTINUE 
	           	}
	           	elseif ( (extract = """") && (multiWord = 1) )
	           	{
		           	set multiWord = 0
		           	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Multi words: " _ cmdArr(arrInd))
		           	Set arrInd = arrInd + 1
		           	SET countup = countup+1
		           	CONTINUE 
	           	}
	           	if (multiWord = 1)
	           	{
		           	SET cmdArr(arrInd) = cmdArr(arrInd) _ " " _ extract
	           	}
	           	else
	           	{
      				SET cmdArr(arrInd) = extract
      				Set arrInd = arrInd + 1
	           	}
      		}
      		SET countup = countup+1
   		}

        set stat = $ZF(-100,"/SHELL", linuxCmd, .cmdArr)
        return stat
